# Reader's own core for the class T (NOTE section 7.2): F = zeta * D_m, m >= 0 atomic on [1, q], m_1 = 1, m_{q/b} = sqrt(q) m_b / b.
# Pi_F = Pi_zeta + log*(m). log*(m) on the monoid G (<= X) generated by the atoms is computed from D' = D * L' :
#   u(x) + sum_{a in A, x/a in G} m_a u(x/a) = m_x log x,   u(x) = log*(m)({x}) log x     (sparse unit-lower-triangular solve).
from fractions import Fraction as Fr
from math import log, isqrt
import numpy as np, scipy.sparse as sp
from scipy.sparse.linalg import spsolve_triangular

def prime_power(n):
    """return k if n = p^k (n integer >= 2), else 0"""
    if n < 2: return 0
    p = 2
    while p * p <= n:
        if n % p == 0:
            k = 0
            while n % p == 0: n //= p; k += 1
            return k if n == 1 else 0
        p += 1
    return 1

class TProbe:
    def __init__(self, q, lower_atoms, X, include_sqrtq=True):
        self.q = Fr(q); sq = isqrt(q); assert sq * sq == q, "q must be a square integer here"
        self.sq = sq
        low = sorted(set(Fr(b) for b in lower_atoms))
        assert all(1 < b < sq for b in low)
        self.low = low
        A = list(low) + [self.q / b for b in low] + ([Fr(sq)] if include_sqrtq else []) + [self.q]
        self.A = A; self.nA = len(A)
        # monoid G <= X generated by A (exact rationals)
        X = Fr(X); G = {Fr(1)}; frontier = [Fr(1)]
        while frontier:
            new = []
            for g in frontier:
                for a in A:
                    h = g * a
                    if h <= X and h not in G: G.add(h); new.append(h)
            frontier = new
        G.discard(Fr(1)); self.G = sorted(G); self.idx = {g: i for i, g in enumerate(self.G)}
        n = len(self.G); self.n = n
        self.logx = np.array([log(g.numerator) - log(g.denominator) for g in self.G])
        self.pz = np.array([(1.0 / prime_power(g.numerator)) if (g.denominator == 1 and prime_power(g.numerator)) else 0.0 for g in self.G])
        rows, cols, aidx = [], [], []
        for i, x in enumerate(self.G):
            for j, a in enumerate(A):
                z = x / a
                if z in self.idx: rows.append(i); cols.append(self.idx[z]); aidx.append(j)
        self.rows = np.array(rows, dtype=np.int64); self.cols = np.array(cols, dtype=np.int64); self.aidx = np.array(aidx, dtype=np.int64)
        self.atpos = np.array([self.idx[a] if a in self.idx else -1 for a in A])
    def masses(self, t, w):
        """t = m_{sqrt q}, w = weights of the lower atoms (same order as self.low)"""
        w = np.asarray(w, float); sq = float(self.sq)
        up = np.array([sq * wi / float(b) for wi, b in zip(w, self.low)])
        return np.concatenate([w, up, [t], [sq]]) if len(self.A) == 2 * len(self.low) + 2 else np.concatenate([w, up, [sq]])
    def Pi(self, t, w):
        mA = self.masses(t, w)
        T = sp.csr_matrix((mA[self.aidx], (self.rows, self.cols)), shape=(self.n, self.n)) + sp.identity(self.n, format='csr')
        rhs = np.zeros(self.n)
        ok = self.atpos >= 0
        rhs[self.atpos[ok]] += mA[ok] * self.logx[self.atpos[ok]]
        u = spsolve_triangular(T, rhs, lower=True)
        return u / self.logx + self.pz
